 1 | // SPDX-License-Identifier: MIT
 2 | pragma solidity ^0.8.0;
 3 | 
 4 | import '../libraries/SafeMath.sol';
 5 | import '../libraries/TransferHelper.sol';
 6 | 
 7 | contract MuteBond {
 8 |     using SafeMath for uint;
 9 | 
10 |     /* ======== EVENTS ======== */
11 | 
12 |     event BondCreated(uint deposit, uint payout, address depositor, uint time);
13 |     event BondPriceChanged(uint internalPrice, uint debtRatio);
14 |     event MaxPriceChanged(uint _price);
15 |     event MaxPayoutChanged(uint _price);
16 |     event EpochDurationChanged(uint _payout);
17 |     event BondLockTimeChanged(uint _duration);
18 |     event StartPriceChanged(uint _lock);
19 | 
20 |      /* ======== STATE VARIABLES ======== */
21 | 
22 |     address immutable private muteToken; // token paid for principal
23 |     address immutable private dMuteToken;
24 |     address immutable private lpToken; // inflow token
25 |     ITreasury immutable private customTreasury; // pays for and receives principal
26 |     uint public bond_time_lock = 7 days; // length of lockup in dMute for bonds
27 | 
28 |     uint public totalPayoutGiven; // total amount of mute paid
29 |     uint public totalDebt; // total amount of LP collected
30 | 
31 |     uint public epochDuration = 7 days; // the length of an epoch from getting from startPrice  to maxPrice
32 |     uint public maxPrice; // max limit price for the LP token (LP:mute ratio)
33 |     uint public startPrice; // start price of the LP token (LP:mute ratio)
34 |     uint public maxPayout; // max amount of mute tokens to sell in each epoch
35 |     uint public epochStart; // timestamp of the current epoch start
36 |     uint public epoch; // amount of cycles for bonds so far
37 | 
38 |     BondTerms[] public terms; // identifies the terms for a bond in a given epoch
39 |     Bonds[] public bonds; // stores individual deposits
40 | 
41 |     // Info for bond epochs
42 |     struct BondTerms {
43 |         uint bondTotal; // amount of tokens bonded so far
44 |         uint payoutTotal;
45 |         uint lastTimestamp;
46 |     }
47 | 
48 |     // Info for a single depositors bond info
49 |     struct Bonds {
50 |         uint value; //
51 |         uint payout; //
52 |         address depositor; //
53 |         uint timestamp;
54 |     }
55 | 
56 | 
57 | 
58 |     /* ======== CONSTRUCTOR ======== */
59 | 
60 |     /**
